import test from 'node:test';import assert from 'node:assert/strict';import {bootstrapProductionAdmin} from './bootstrap-production-admin.js';
const input={email:'operator@example.org',password:'private-random-password-'.repeat(3)};
function fixture({admin=false,user=false,locked=false}={}){const queries=[];let released=false;const db={query:async(sql,args)=>{queries.push({sql,args});if(sql.includes('GET_LOCK'))return {rows:[{acquired:locked?0:1}]};if(sql.includes("role='super_admin'"))return {rows:admin?[{id:'admin'}]:[]};if(sql==='SELECT id FROM users LIMIT 1')return {rows:user?[{id:'user'}]:[]};return {rows:[]};},release:()=>{released=true;}};return {pool:{connect:async()=>db},queries,released:()=>released};}
test('initial admin only created in empty database with forced password change',async()=>{const f=fixture();assert.equal((await bootstrapProductionAdmin(f.pool,input)).created,true);const insert=f.queries.find(q=>q.sql.startsWith('INSERT'));assert.ok(insert.sql.includes('must_change_password'));assert.ok(insert.sql.includes("'super_admin','active',TRUE"));assert.equal(insert.args[2],input.email);assert.equal(insert.args[4].includes(input.password),false);assert.equal(f.released(),true);});
test('existing administrator and passwords remain unchanged',async()=>{const f=fixture({admin:true});assert.equal((await bootstrapProductionAdmin(f.pool,input)).created,false);assert.equal(f.queries.some(q=>q.sql.startsWith('INSERT')||q.sql.startsWith('UPDATE')),false);});
test('existing regular users are never silently elevated',async()=>{const f=fixture({user:true});await assert.rejects(()=>bootstrapProductionAdmin(f.pool,input),/manual account review/);assert.equal(f.queries.some(q=>q.sql.startsWith('INSERT')||q.sql.startsWith('UPDATE')),false);assert.equal(f.released(),true);});
test('lock contention blocks duplicate bootstrap and still releases connection',async()=>{const f=fixture({locked:true});await assert.rejects(()=>bootstrapProductionAdmin(f.pool,input),/locked/);assert.equal(f.released(),true);});
